<?php
declare(strict_types=1);

/**
 * MRL Weekly Standings v063 Installer
 *
 * VERSION: v001
 * LAST MODIFIED: 7/22/2026 12:05:24 pm
 *
 * Installs weekly_standings.php v063 as a complete-file replacement.
 * Run from /race_results/, verify success, then delete this installer.
 */

header('Content-Type: text/html; charset=UTF-8');

function installer_h($value): string
{
    return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
}

$target = __DIR__ . '/weekly_standings.php';
$payloadBase64 = <<<'PAYLOAD'

PAYLOAD;
$expectedSha256 = '84cfacdb95d3866bb1f5111f7c9bd0e04388e24647aa2ba915dfef34d1e0a6f3';
$report = [];
$errors = [];

if (!is_file($target)) {
    $errors[] = 'Target file not found: weekly_standings.php';
}

$current = is_file($target) ? file_get_contents($target) : false;
if ($current === false && is_file($target)) {
    $errors[] = 'Unable to read weekly_standings.php.';
}

if (is_string($current)) {
    if (strpos($current, 'VERSION: v062') === false && strpos($current, 'VERSION: v063') === false) {
        $errors[] = 'Preflight stopped: weekly_standings.php is not the expected v062/v063 baseline.';
    }

    $requiredAnchors = [
        'function printWeeklyReport()',
        'function exportWeeklyStandingsXlsx()',
        'class="release-version-row"',
        '@media print',
    ];

    foreach ($requiredAnchors as $anchor) {
        if (strpos($current, $anchor) === false) {
            $errors[] = 'Preflight stopped: required anchor not found — ' . $anchor;
        }
    }
}

$payload = base64_decode($payloadBase64, true);
if (!is_string($payload) || $payload === '') {
    $errors[] = 'Installer payload could not be decoded.';
} elseif (hash('sha256', $payload) !== $expectedSha256) {
    $errors[] = 'Installer payload checksum failed.';
}

if (empty($errors) && is_string($current) && hash('sha256', $current) === $expectedSha256) {
    $report[] = 'weekly_standings.php is already v063 and matches this installer.';
} elseif (empty($errors)) {
    $backupStamp = date('Ymd_His');
    $backup = __DIR__ . '/weekly_standings.php.bak_' . $backupStamp;

    if (!copy($target, $backup)) {
        $errors[] = 'Unable to create backup: ' . basename($backup);
    } else {
        $report[] = 'Backup created: ' . basename($backup);
    }

    if (empty($errors)) {
        $temp = $target . '.tmp_' . bin2hex(random_bytes(4));
        $bytes = file_put_contents($temp, $payload, LOCK_EX);

        if ($bytes !== strlen($payload)) {
            @unlink($temp);
            $errors[] = 'Unable to write the complete replacement file.';
        } elseif (hash_file('sha256', $temp) !== $expectedSha256) {
            @unlink($temp);
            $errors[] = 'Temporary-file checksum verification failed.';
        } elseif (!rename($temp, $target)) {
            @unlink($temp);
            $errors[] = 'Unable to move the replacement file into place.';
        } else {
            @chmod($target, 0644);
            $report[] = 'Updated: weekly_standings.php';
            $report[] = 'Installed version: v063';
        }
    }
}

$success = empty($errors);
?>
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>MRL Weekly Standings v063 Installer</title>
    <style>
        body { font-family: Arial, Helvetica, sans-serif; margin: 24px; color: #111; }
        .card { max-width: 900px; padding: 18px 22px; border: 2px solid <?php echo $success ? '#1f5f3b' : '#8b0000'; ?>; border-radius: 10px; background: <?php echo $success ? '#eefaf2' : '#fff0f0'; ?>; }
        h1 { margin-top: 0; font-size: 24px; }
        .status { font-weight: bold; font-size: 18px; }
        li { margin: 6px 0; }
        code { background: rgba(0,0,0,.06); padding: 1px 4px; }
    </style>
</head>
<body>
<div class="card">
    <h1>MRL Weekly Standings v063 Installer</h1>
    <p class="status"><?php echo $success ? 'SUCCESS — weekly_standings.php was installed.' : 'STOPPED — no successful installation was completed.'; ?></p>

    <?php if (!empty($report)): ?>
        <h2>Report</h2>
        <ul>
            <?php foreach ($report as $line): ?>
                <li><?php echo installer_h($line); ?></li>
            <?php endforeach; ?>
        </ul>
    <?php endif; ?>

    <?php if (!empty($errors)): ?>
        <h2>Errors</h2>
        <ul>
            <?php foreach ($errors as $line): ?>
                <li><?php echo installer_h($line); ?></li>
            <?php endforeach; ?>
        </ul>
    <?php endif; ?>

    <?php if ($success): ?>
        <p>Test Print and Spreadsheet on a current race and a superseded release. After confirmation, delete this installer.</p>
    <?php else: ?>
        <p>The installer stopped because its preflight or write verification did not pass. Leave the existing file and any backup in place.</p>
    <?php endif; ?>
</div>
</body>
</html>
